function memoize(fn) {
  const cache = new Map();
  return (...args) => {
    const key = JSON.stringify(args);
    if (!cache.has(key)) cache.set(key, fn(...args));
    return cache.get(key);
  };
}

let runs = 0;
const area = memoize((room) => {
  runs += 1;
  return room.w * room.h;
});

const hall = { w: 2, h: 5 };
console.log(area(hall));
hall.w = 4;
console.log(area(hall));
console.log(area({ h: 5, w: 4 }));
console.log(area({ w: 4, h: 5 }));
console.log(runs);
